import { useState } from 'react';
import { Link } from 'react-router-dom';
import styles from './ContactPage.module.css';

function ContactPage() {
  const [darkMode, setDarkMode] = useState(false);
  const [formData, setFormData] = useState({ name: '', email: '', message: '' });
  const [submitted, setSubmitted] = useState(false);

  const toggleTheme = () => setDarkMode(prev => !prev);

  const handleChange = (e) => {
    setFormData({ ...formData, [e.target.name]: e.target.value });
  };

  const handleSubmit = (e) => {
    e.preventDefault();
    console.log('Form submitted:', formData);
    setSubmitted(true);
  };

  return (
    <div className={darkMode ? styles['dark-mode'] : ''}>
      <header className={styles.header}>
        <h1>Contact Me</h1>
        <nav>
          <ul className={styles.navList}>
            <li><Link to="/">Home</Link></li>
            <li><Link to="/about">About</Link></li>
            <li><Link to="/contact" className={styles.active}>Contact</Link></li>
            <li><Link to="/register">Register</Link></li>
            <li><Link to="/game">Game</Link></li>
          </ul>
        </nav>
      </header>

      <button className={styles.themeToggle} onClick={toggleTheme}>
        Toggle Dark/Light
      </button>

      {submitted ? (
        <p className={styles.successMessage}>Thanks, {formData.name}! Message received.</p>
      ) : (
        <form className={styles.form} onSubmit={handleSubmit}>
          <label>Name</label>
          <input type="text" name="name" value={formData.name} onChange={handleChange} required />

          <label>Email</label>
          <input type="email" name="email" value={formData.email} onChange={handleChange} required />

          <label>Message</label>
          <textarea name="message" value={formData.message} onChange={handleChange} required />

          <button type="submit">Send Message</button>
        </form>
      )}

      <footer className={styles.footer}>
        <p>Contact: dxxxxxxxxxxx@gmail.com | Phone: 09xxxxxxx8</p>
        <p>&copy; 2026 My Personal Portfolio. All rights reserved.</p>
      </footer>
    </div>
  );
}

export default ContactPage;
